CREATE TRIGGER "trg_phase717_cancel_terminal_invitation_email"
    AFTER UPDATE OF "status" ON "public"."platform_admin_invitations"
    FOR EACH ROW EXECUTE FUNCTION "public"."phase717_cancel_terminal_invitation_email"();

CREATE TRIGGER "phase81_admin_audit_append_only"
    BEFORE UPDATE OR DELETE ON "public"."admin_audit_log"
    FOR EACH ROW EXECUTE FUNCTION "public"."phase81_prevent_audit_mutation"();

CREATE TRIGGER trg_faculty_attendance_rosters_updated_at
BEFORE UPDATE ON public.faculty_attendance_rosters
FOR EACH ROW EXECUTE FUNCTION public.faculty_attendance_set_updated_at();

